To flatten an array using the reduce method in JavaScript:

```javascript
// Basic: flatten one level
const nested = [[1, 2], [3, 4], [5, 6]];
const flat = nested.reduce((acc, curr) => acc.concat(curr), []);
console.log(flat); // [1, 2, 3, 4, 5, 6]

// Flatten with spread operator
const flat2 = nested.reduce((acc, curr) => [...acc, ...curr], []);

// Flatten multiple levels (recursive)
function flattenDeep(arr) {
  return arr.reduce((acc, curr) => {
    return acc.concat(Array.isArray(curr) ? flattenDeep(curr) : curr);
  }, []);
}

const deeplyNested = [1, [2, 3], [4, [5, 6]]];
console.log(flattenDeep(deeplyNested)); // [1, 2, 3, 4, 5, 6]

// With depth control
function flattenWithDepth(arr, depth = 1) {
  return arr.reduce((acc, curr) => {
    if (Array.isArray(curr) && depth > 0) {
      return acc.concat(flattenWithDepth(curr, depth - 1));
    }
    return acc.concat(curr);
  }, []);
}

// Alternative: using Array.flat() (ES2019) - built-in method
console.log(nested.flat());        // [1, 2, 3, 4, 5, 6]
console.log(deeplyNested.flat(2)); // [1, 2, 3, 4, 5, 6]
```

The reduce approach is useful when you need custom flattening logic. For simple cases, Array.flat() is cleaner.
